import { cp, rm, writeFile } from "node:fs/promises";
import { resolve } from "node:path";

const root = resolve(import.meta.dirname, "..");
const source = resolve(
  root,
  "node_modules",
  "@capacitor",
  "android",
  "capacitor",
);
const destination = resolve(root, "android", "capacitor-android");
const settings = resolve(root, "android", "capacitor.settings.gradle");

await rm(destination, { recursive: true, force: true });
await cp(source, destination, { recursive: true });
await writeFile(
  settings,
  [
    "// Generated by Capacitor, then adjusted for the standalone Windows package.",
    "include ':capacitor-android'",
    "project(':capacitor-android').projectDir = new File(rootDir, 'capacitor-android')",
    "",
  ].join("\n"),
  "utf8",
);

console.log("Capacitor Android 모듈을 프로젝트 내부에 준비했습니다.");
